-- ============================================================
-- Project: CS_AHF_earlysepsis12
-- File: sql/03_features/081A_export_qc_and_dataset.sql
-- Purpose:
--   Export QC files and the structured echo screen feature table.
--
-- Note:
--   psql \copy must be written as a single logical line.
-- ============================================================

\copy (select count(*) as n_total, sum(primary_outcome_flag) as n_events, round(sum(primary_outcome_flag) * 100.0 / count(*), 2) as event_rate, sum(echo_any_procedure_pre12_flag) as n_echo_any_pre12, round(sum(echo_any_procedure_pre12_flag) * 100.0 / count(*), 2) as pct_echo_any_pre12, sum(tte_procedure_pre12_flag) as n_tte_pre12, round(sum(tte_procedure_pre12_flag) * 100.0 / count(*), 2) as pct_tte_pre12, sum(tee_procedure_pre12_flag) as n_tee_pre12, round(sum(tee_procedure_pre12_flag) * 100.0 / count(*), 2) as pct_tee_pre12, sum(echo_any_procedure_0_12h_flag) as n_echo_any_0_12h, round(sum(echo_any_procedure_0_12h_flag) * 100.0 / count(*), 2) as pct_echo_any_0_12h, sum(structured_lvef_pre12_available_flag) as n_structured_lvef_pre12, round(sum(structured_lvef_pre12_available_flag) * 100.0 / count(*), 2) as pct_structured_lvef_pre12, sum(cardiac_output_0_12h_available_flag) as n_cardiac_output_0_12h, round(sum(cardiac_output_0_12h_available_flag) * 100.0 / count(*), 2) as pct_cardiac_output_0_12h, sum(cardiac_index_0_12h_available_flag) as n_cardiac_index_0_12h, round(sum(cardiac_index_0_12h_available_flag) * 100.0 / count(*), 2) as pct_cardiac_index_0_12h from study_ahf.model_081A_structured_echo_screen_0_12h_v1) to '/Users/zheyu/Desktop/CS_AHF_landmark24/sql_results/081A_QC1_overall.csv' csv header;

\copy (select count(*) as n_total, sum(structured_lvef_pre12_available_flag) as n_lvef_available, min(structured_lvef_pre12_last) as lvef_last_min, percentile_cont(0.25) within group (order by structured_lvef_pre12_last) filter (where structured_lvef_pre12_available_flag = 1) as lvef_last_p25, percentile_cont(0.50) within group (order by structured_lvef_pre12_last) filter (where structured_lvef_pre12_available_flag = 1) as lvef_last_p50, percentile_cont(0.75) within group (order by structured_lvef_pre12_last) filter (where structured_lvef_pre12_available_flag = 1) as lvef_last_p75, max(structured_lvef_pre12_last) as lvef_last_max, sum(structured_lvef_last_lt40_flag) as n_lvef_last_lt40, sum(structured_lvef_last_lt50_flag) as n_lvef_last_lt50 from study_ahf.model_081A_structured_echo_screen_0_12h_v1) to '/Users/zheyu/Desktop/CS_AHF_landmark24/sql_results/081A_QC2_lvef_structured_availability.csv' csv header;

\copy (select case when echo_any_procedure_pre12_flag = 1 then '01_echo_pre12_available' else '00_no_echo_procedure_pre12' end as echo_procedure_group, count(*) as n, sum(primary_outcome_flag) as events, round(sum(primary_outcome_flag) * 100.0 / count(*), 2) as event_rate from study_ahf.model_081A_structured_echo_screen_0_12h_v1 group by case when echo_any_procedure_pre12_flag = 1 then '01_echo_pre12_available' else '00_no_echo_procedure_pre12' end order by echo_procedure_group) to '/Users/zheyu/Desktop/CS_AHF_landmark24/sql_results/081A_QC3_event_rate_by_echo_availability.csv' csv header;

\copy (select count(*) as n_total, sum(cardiac_output_0_12h_available_flag) as n_cardiac_output_available, min(cardiac_output_0_12h_mean) as cardiac_output_mean_min, percentile_cont(0.50) within group (order by cardiac_output_0_12h_mean) filter (where cardiac_output_0_12h_available_flag = 1) as cardiac_output_mean_p50, max(cardiac_output_0_12h_mean) as cardiac_output_mean_max, sum(cardiac_index_0_12h_available_flag) as n_cardiac_index_available, min(cardiac_index_0_12h_mean) as cardiac_index_mean_min, percentile_cont(0.50) within group (order by cardiac_index_0_12h_mean) filter (where cardiac_index_0_12h_available_flag = 1) as cardiac_index_mean_p50, max(cardiac_index_0_12h_mean) as cardiac_index_mean_max from study_ahf.model_081A_structured_echo_screen_0_12h_v1) to '/Users/zheyu/Desktop/CS_AHF_landmark24/sql_results/081A_QC4_co_ci_availability_ranges.csv' csv header;

\copy (select * from study_ahf.model_081A_structured_echo_screen_0_12h_v1) to '/Users/zheyu/Desktop/CS_AHF_landmark24/CS_AHF_hemodynamic_deterioration_ml_project/data/raw/model_081A_structured_echo_screen_0_12h_features.csv' csv header;
